from __future__ import annotations

import argparse
import json
import re
from dataclasses import dataclass
from pathlib import Path

from PIL import Image, ImageChops, ImageDraw, ImageFont


IMG_EXTS = {".png", ".jpg", ".jpeg", ".tif", ".tiff"}
RUN_DIR_RE = re.compile(r"^(?P<mode>[a-zA-Z0-9_]+)_strength_(?P<tag>[mp0-9]+)$")


@dataclass(frozen=True)
class SweepRun:
    pc_name: str
    mode: str
    strength: float
    run_dir: Path


def _build_argparser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(
        description="Build comparison grids from outputs generated by scripts/run/test_uni_pca_sweep.sh."
    )
    ap.add_argument(
        "--orig-dir",
        type=Path,
        required=True,
        help="Directory of original tile images used for the sweep (e.g. cf_imgs/roi3_neg1_tiles).",
    )
    ap.add_argument(
        "--sweep-root",
        type=Path,
        required=True,
        help="Root directory of UNI PCA sweep outputs (contains pc_*/<mode>_strength_*/...).",
    )
    ap.add_argument("--out-dir", type=Path, required=True, help="Output directory for summary grids.")
    ap.add_argument(
        "--tile-limit",
        type=int,
        default=24,
        help="Max number of tiles to include in summary grids (0 = all).",
    )
    ap.add_argument(
        "--pc-limit",
        type=int,
        default=0,
        help="Max number of PCA components to include in by_tile grids (0 = all discovered PCs).",
    )
    ap.add_argument(
        "--strengths",
        type=str,
        default="",
        help="Optional comma-separated strengths to include (e.g. -1,-0.5,0.5,1). Default: all discovered.",
    )
    ap.add_argument(
        "--thumb-size",
        type=int,
        default=192,
        help="Resize tiles to square thumbnails of this size for summary grids.",
    )
    ap.add_argument(
        "--include-diff",
        action="store_true",
        help="Also save abs-difference grids (edit vs original) for by_pc and by_tile views.",
    )
    return ap


def _parse_strength_tag(tag: str) -> float:
    # Sweep script encodes -1.0 -> m1p0, 0.25 -> 0p25
    s = tag.replace("m", "-", 1) if tag.startswith("m") else tag
    s = s.replace("p", ".")
    return float(s)


def _parse_strength_csv(val: str) -> list[float]:
    if not val.strip():
        return []
    return [float(x.strip()) for x in val.split(",") if x.strip()]


def _gather_tiles(orig_dir: Path) -> list[Path]:
    files = sorted([p for p in orig_dir.iterdir() if p.is_file() and p.suffix.lower() in IMG_EXTS])
    if not files:
        raise SystemExit(f"No tile images found in {orig_dir}")
    return files


def _discover_runs(sweep_root: Path) -> list[SweepRun]:
    runs: list[SweepRun] = []
    for pc_dir in sorted([p for p in sweep_root.iterdir() if p.is_dir() and p.name.startswith("pc_")]):
        for run_dir in sorted([p for p in pc_dir.iterdir() if p.is_dir()]):
            m = RUN_DIR_RE.match(run_dir.name)
            if not m:
                continue
            runs.append(
                SweepRun(
                    pc_name=pc_dir.name,
                    mode=m.group("mode"),
                    strength=_parse_strength_tag(m.group("tag")),
                    run_dir=run_dir,
                )
            )
    if not runs:
        raise SystemExit(f"No sweep runs found under {sweep_root}")
    return runs


def _load_img_rgb(path: Path, thumb_size: int) -> Image.Image:
    im = Image.open(path).convert("RGB")
    if thumb_size > 0 and im.size != (thumb_size, thumb_size):
        im = im.resize((thumb_size, thumb_size), resample=Image.BILINEAR)
    return im


def _abs_diff_img(orig: Image.Image, edit: Image.Image) -> Image.Image:
    a = orig
    b = edit
    if a.size != b.size:
        b = b.resize(a.size, resample=Image.BILINEAR)
    return ImageChops.difference(a, b)


def _placeholder(size: tuple[int, int], text: str) -> Image.Image:
    im = Image.new("RGB", size, (245, 245, 245))
    d = ImageDraw.Draw(im)
    font = ImageFont.load_default()
    d.rectangle([0, 0, size[0] - 1, size[1] - 1], outline=(180, 180, 180))
    d.text((6, 6), text, fill=(80, 80, 80), font=font)
    return im


def _make_labeled_grid(
    *,
    images: list[list[Image.Image]],
    row_labels: list[str],
    col_labels: list[str],
    out_path: Path,
    title: str,
    cell_gap: int = 6,
    header_h: int = 26,
    row_label_w: int = 180,
    title_h: int = 28,
) -> None:
    if not images or not images[0]:
        raise ValueError("Empty image grid")
    n_rows = len(images)
    n_cols = len(images[0])
    if any(len(row) != n_cols for row in images):
        raise ValueError("Grid rows have inconsistent column counts")
    if len(row_labels) != n_rows:
        raise ValueError("row_labels length mismatch")
    if len(col_labels) != n_cols:
        raise ValueError("col_labels length mismatch")

    cell_w, cell_h = images[0][0].size
    grid_w = row_label_w + n_cols * cell_w + (n_cols - 1) * cell_gap
    grid_h = title_h + header_h + n_rows * cell_h + (n_rows - 1) * cell_gap

    canvas = Image.new("RGB", (grid_w, grid_h), (255, 255, 255))
    draw = ImageDraw.Draw(canvas)
    font = ImageFont.load_default()

    draw.text((8, 6), title, fill=(0, 0, 0), font=font)

    # Column headers
    for c, label in enumerate(col_labels):
        x = row_label_w + c * (cell_w + cell_gap)
        y = title_h + 4
        draw.text((x + 4, y), label, fill=(0, 0, 0), font=font)

    # Row labels + cells
    y0 = title_h + header_h
    for r, (row_label, row_imgs) in enumerate(zip(row_labels, images)):
        y = y0 + r * (cell_h + cell_gap)
        draw.text((8, y + 4), row_label, fill=(0, 0, 0), font=font)
        for c, im in enumerate(row_imgs):
            x = row_label_w + c * (cell_w + cell_gap)
            canvas.paste(im, (x, y))

    out_path.parent.mkdir(parents=True, exist_ok=True)
    canvas.save(out_path)


def _find_edit_image(run_dir: Path, tile_stem: str) -> Path | None:
    p = run_dir / tile_stem / "uni_steer_edit.png"
    if p.exists():
        return p
    return None


def _sort_pcs(pc_names: list[str]) -> list[str]:
    def key_fn(name: str) -> tuple[int, str]:
        try:
            return (int(name.split("_")[1]), name)
        except Exception:
            return (10**9, name)

    return sorted(pc_names, key=key_fn)


def _sort_strengths(vals: list[float]) -> list[float]:
    return sorted(vals)


def main() -> None:
    args = _build_argparser().parse_args()

    orig_tiles = _gather_tiles(args.orig_dir)
    if args.tile_limit and args.tile_limit > 0:
        orig_tiles = orig_tiles[: int(args.tile_limit)]

    runs = _discover_runs(args.sweep_root)
    requested_strengths = _parse_strength_csv(args.strengths)

    # Group runs by component.
    runs_by_pc: dict[str, dict[float, SweepRun]] = {}
    modes_seen: set[str] = set()
    for r in runs:
        modes_seen.add(r.mode)
        runs_by_pc.setdefault(r.pc_name, {})[float(r.strength)] = r

    if len(modes_seen) > 1:
        print(f"[warn] Multiple modes found in sweep root: {sorted(modes_seen)}")
    mode_name = sorted(modes_seen)[0] if modes_seen else "delta"

    pc_names = _sort_pcs(list(runs_by_pc.keys()))
    if args.pc_limit and args.pc_limit > 0:
        pc_names = pc_names[: int(args.pc_limit)]

    discovered_strengths = _sort_strengths(sorted({s for pc in pc_names for s in runs_by_pc[pc].keys()}))
    strengths = requested_strengths or discovered_strengths
    strengths = _sort_strengths([s for s in strengths if s in set(discovered_strengths)])
    if not strengths:
        raise SystemExit("No matching strengths found to visualize.")

    out_dir = args.out_dir
    by_pc_dir = out_dir / "by_pc"
    by_tile_dir = out_dir / "by_tile"
    by_pc_diff_dir = out_dir / "by_pc_diff"
    by_tile_diff_dir = out_dir / "by_tile_diff"
    out_dir.mkdir(parents=True, exist_ok=True)

    print(f"Tiles selected: {len(orig_tiles)}")
    print(f"PCs selected: {len(pc_names)}")
    print(f"Strengths: {strengths}")

    # Cache resized originals and edits to avoid repeated disk I/O.
    orig_cache: dict[str, Image.Image] = {}
    edit_cache: dict[tuple[str, str, float], Image.Image] = {}
    thumb = int(args.thumb_size)

    for tile_path in orig_tiles:
        orig_cache[tile_path.stem] = _load_img_rgb(tile_path, thumb)

    for pc in pc_names:
        for s in strengths:
            run = runs_by_pc.get(pc, {}).get(s)
            if run is None:
                continue
            for tile_path in orig_tiles:
                p = _find_edit_image(run.run_dir, tile_path.stem)
                if p is not None and p.exists():
                    edit_cache[(pc, tile_path.stem, s)] = _load_img_rgb(p, thumb)

    # 1) Per-PC grids: rows are tiles, columns are orig + strengths.
    print("[1/3] Building per-PC grids...")
    col_labels = ["orig"] + [f"{s:+g}" for s in strengths]
    for pc in pc_names:
        rows_rgb: list[list[Image.Image]] = []
        rows_diff: list[list[Image.Image]] = []
        row_labels: list[str] = []
        for tile_path in orig_tiles:
            stem = tile_path.stem
            orig_im = orig_cache[stem]
            row = [orig_im]
            row_diff = [_placeholder(orig_im.size, "n/a")]
            for s in strengths:
                edit_im = edit_cache.get((pc, stem, s))
                if edit_im is None:
                    row.append(_placeholder(orig_im.size, "missing"))
                    row_diff.append(_placeholder(orig_im.size, "missing"))
                else:
                    row.append(edit_im)
                    if args.include_diff:
                        row_diff.append(_abs_diff_img(orig_im, edit_im))
            rows_rgb.append(row)
            rows_diff.append(row_diff)
            row_labels.append(stem)

        _make_labeled_grid(
            images=rows_rgb,
            row_labels=row_labels,
            col_labels=col_labels,
            out_path=by_pc_dir / f"{pc}_{mode_name}.png",
            title=f"{pc} | mode={mode_name} | rows=tiles | cols=orig+strengths",
        )
        if args.include_diff:
            _make_labeled_grid(
                images=rows_diff,
                row_labels=row_labels,
                col_labels=col_labels,
                out_path=by_pc_diff_dir / f"{pc}_{mode_name}_absdiff.png",
                title=f"{pc} | ABS DIFF vs orig | mode={mode_name}",
            )

    # 2) Per-tile grids: rows are PCs, columns are orig + strengths.
    print("[2/3] Building per-tile grids...")
    for tile_path in orig_tiles:
        stem = tile_path.stem
        orig_im = orig_cache[stem]
        rows_rgb: list[list[Image.Image]] = []
        rows_diff: list[list[Image.Image]] = []
        row_labels: list[str] = []
        for pc in pc_names:
            row = [orig_im]
            row_diff = [_placeholder(orig_im.size, "n/a")]
            for s in strengths:
                edit_im = edit_cache.get((pc, stem, s))
                if edit_im is None:
                    row.append(_placeholder(orig_im.size, "missing"))
                    row_diff.append(_placeholder(orig_im.size, "missing"))
                else:
                    row.append(edit_im)
                    if args.include_diff:
                        row_diff.append(_abs_diff_img(orig_im, edit_im))
            rows_rgb.append(row)
            rows_diff.append(row_diff)
            row_labels.append(pc)

        _make_labeled_grid(
            images=rows_rgb,
            row_labels=row_labels,
            col_labels=col_labels,
            out_path=by_tile_dir / f"{stem}_{mode_name}.png",
            title=f"{stem} | mode={mode_name} | rows=PCs | cols=orig+strengths",
        )
        if args.include_diff:
            _make_labeled_grid(
                images=rows_diff,
                row_labels=row_labels,
                col_labels=col_labels,
                out_path=by_tile_diff_dir / f"{stem}_{mode_name}_absdiff.png",
                title=f"{stem} | ABS DIFF vs orig | mode={mode_name}",
            )

    # 3) Write summary metadata for reproducibility.
    print("[3/3] Writing summary metadata...")
    summary = {
        "orig_dir": str(args.orig_dir),
        "sweep_root": str(args.sweep_root),
        "out_dir": str(out_dir),
        "mode": mode_name,
        "tile_count": len(orig_tiles),
        "pc_count": len(pc_names),
        "strengths": strengths,
        "thumb_size": int(args.thumb_size),
        "include_diff": bool(args.include_diff),
        "tiles": [p.name for p in orig_tiles],
        "pcs": pc_names,
    }
    (out_dir / "summary_meta.json").write_text(json.dumps(summary, indent=2))

    print("Saved summary grids:")
    print(f"  by_pc:   {by_pc_dir}")
    print(f"  by_tile: {by_tile_dir}")
    if args.include_diff:
        print(f"  by_pc_diff:   {by_pc_diff_dir}")
        print(f"  by_tile_diff: {by_tile_diff_dir}")


if __name__ == "__main__":
    main()
